ndard","source_reference":"Supplied examination photo 10, Requirements, UML and testing [SHA-256 9fe400b4c14505c025a738ed6fa9a8066f65a4a7afd67e38f3d7e1ddf048f31f]"},{"course_code":"SEN 201","topic":2,"photo_lesson":true,"logical_question_key":"sen-201-photo20261025-t2-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which testing checks whether a delivered system meets agreed user needs?","options":[{"label":"A","body":"Unconditional deployment"},{"label":"B","body":"Source formatting"},{"label":"C","body":"Acceptance testing"},{"label":"D","body":"Lexical analysis"}],"correct_option":"C","explanation":"Acceptance testing evaluates agreed stakeholder criteria.","answer_format":"standard","source_reference":"Supplied examination photo 10, Requirements, UML and testing [SHA-256 9fe400b4c14505c025a738ed6fa9a8066f65a4a7afd67e38f3d7e1ddf048f31f]"},{"course_code":"SEN 201","topic":2,"photo_lesson":true,"logical_question_key":"sen-201-photo20261025-t2-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"Testing whether a delivered system meets agreed stakeholder needs is ____ testing.","explanation":"Acceptance testing evaluates agreed stakeholder criteria.","gaps":[{"index":0,"accepted_answers":["acceptance"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 10, Requirements, UML and testing [SHA-256 9fe400b4c14505c025a738ed6fa9a8066f65a4a7afd67e38f3d7e1ddf048f31f]"},{"course_code":"SEN 201","topic":2,"photo_lesson":true,"logical_question_key":"sen-201-photo20261025-t2-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"A UML ____ diagram shows actors and their system goals.","explanation":"The reviewed lesson explains why the answer is use case.","gaps":[{"index":0,"accepted_answers":["use case","use-case"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_refe