D","body":"Binary"}],"correct_option":"C","explanation":"Operational feasibility considers how the solution will work in practice.","answer_format":"standard","source_reference":"Supplied examination photo 11, Feasibility, engineering roles and quality [SHA-256 4eee7e3965e391fcfa697fcc9a10219a4006ba0ea3eee14a97f8a14d2b304f78]"},{"course_code":"SEN 201","topic":3,"photo_lesson":true,"logical_question_key":"sen-201-photo20261025-t3-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which is a core software-engineering responsibility?","options":[{"label":"A","body":"Publishing known defects without review"},{"label":"B","body":"Testing and maintaining software"},{"label":"C","body":"Avoiding all stakeholder communication"},{"label":"D","body":"Assuming requirements never change"}],"correct_option":"B","explanation":"Testing and maintenance are essential engineering activities.","answer_format":"standard","source_reference":"Supplied examination photo 11, Feasibility, engineering roles and quality [SHA-256 4eee7e3965e391fcfa697fcc9a10219a4006ba0ea3eee14a97f8a14d2b304f78]"},{"course_code":"SEN 201","topic":3,"photo_lesson":true,"logical_question_key":"sen-201-photo20261025-t3-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"Feasibility that compares costs and benefits is ____ feasibility.","explanation":"Economic feasibility concerns financial viability.","gaps":[{"index":0,"accepted_answers":["economic"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 11, Feasibility, engineering roles and quality [SHA-256 4eee7e3965e391fcfa697fcc9a10219a4006ba0ea3eee14a97f8a14d2b304f78]"},{"course_code":"SEN 201","topic":3,"photo_lesson":true,"logical_question_key":"sen-201-photo20261025-t3-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"Feasibility that checks technology and skills is ____ feasibility.","explanation":"Technical feasibility checks the means to build and run the system.","gaps":[{"index":0,"accepted_answers":["technical"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 11, Feasibility, engineering roles and quality [SHA-256 4eee7e3965e391fcfa697fcc9a10219a4006ba0ea3eee14a97f8a14d2b304f78]"},{"course_code":"CYB 201","topic":1,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t1-q1","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which security goal is most directly harmed by unauthorised disclosure?","options":[{"label":"A","body":"Usability only"},{"label":"B","body":"Compression"},{"label":"C","body":"Confidentiality"},{"label":"D","body":"Availability only"}],"correct_option":"C","explanation":"Confidentiality concerns limiting information disclosure.","answer_format":"standard","source_reference":"Supplied examination photo 12, Security goals, risk, least privilege and response [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":1,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t1-q2","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"An unpatched software defect is best classified as what?","options":[{"label":"A","body":"A proof of safety"},{"label":"B","body":"A vulnerability"},{"label":"C","body":"A complete risk calculation"},{"label":"D","body":"A backup plan"}],"correct_option":"B","explanation":"A vulnerability is a weakness that could be exploited.","answer_format":"standard","source_reference":"Supplied examination photo 12, Security goals, risk, least privilege and response [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":1,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t1-q3","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which practice implements least privilege?","options":[{"label":"A","body":"Grant only permissions required for the task"},{"label":"B","body":"Make every account an administrator"},{"label":"C","body":"Share one privileged password"},{"label":"D","body":"Disable all access review"}],"correct_option":"A","explanation":"Least privilege limits authority to necessary functions.","answer_format":"standard","source_reference":"Supplied examination photo 12, Security goals, risk, least privilege and response [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":1,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t1-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which initial ARPANET site was not a university?","options":[{"label":"A","body":"UCLA"},{"label":"B","body":"UC Santa Barbara"},{"label":"C","body":"University of Utah"},{"label":"D","body":"Stanford Research Institute"}],"correct_option":"D","explanation":"SRI was a research institute; it should not be confused with Stanford University.","answer_format":"standard","source_reference":"Supplied examination photo 12, Security goals, risk, least privilege and response [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":1,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t1-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"The CIA goal protecting information from unauthorised disclosure is ____.","explanation":"Confidentiality concerns limiting information disclosure.","gaps":[{"index":0,"accepted_answers":["confidentiality"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 12, Security goals, risk, least privilege and response [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":1,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t1-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"A weakness that a threat could exploit is a ____.","explanation":"A vulnerability is a weakness that could be exploited.","gaps":[{"index":0,"accepted_answers":["vulnerability"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 12, Security goals, risk, least privilege and response [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":2,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t2-q1","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which OSI layer provides routing between networks?","options":[{"label":"A","body":"Session"},{"label":"B","body":"Network"},{"label":"C","body":"Physical"},{"label":"D","body":"Presentation"}],"correct_option":"B","explanation":"The Network layer supports logical addressing and routing.","answer_format":"standard","source_reference":"Supplied examination photo 4, Network models, firewalls and common threats [SHA-256 119c9dfa2ba2d363e147557a7d894bfe9c2a831e43613e94993e2c2e20e8b81b]"},{"course_code":"CYB 201","topic":2,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t2-q2","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which is the application-side top layer of OSI?","options":[{"label":"A","body":"Application"},{"label":"B","body":"Physical"},{"label":"C","body":"Data Link"},{"label":"D","body":"Network"}],"correct_option":"A","explanation":"Application is the seventh OSI layer.","answer_format":"standard","source_reference":"Supplied examination photo 4, Network models, firewalls and common threats [SHA-256 119c9dfa2ba2d363e147557a7d894bfe9c2a831e43613e94993e2c2e20e8b81b]"},{"course_code":"CYB 201","topic":2,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t2-q3","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What is the primary function of a firewall?","options":[{"label":"A","body":"Guarantee every application has no defects"},{"label":"B","body":"Replace every user password"},{"label":"C","body":"Make backups unnecessary"},{"label":"D","body":"Enforce traffic rules"}],"correct_option":"D","explanation":"A firewall allows or blocks traffic according to policy.","answer_format":"standard","source_reference":"Supplied examination photo 4, Network models, firewalls and common threats [SHA-256 119c9dfa2ba2d363e147557a7d894bfe9c2a831e43613e94993e2c2e20e8b81b]"},{"course_code":"CYB 201","topic":2,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t2-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What characterises a distributed denial-of-service attack?","options":[{"label":"A","body":"A normal scheduled backup"},{"label":"B","body":"A patch fixes a defect"},{"label":"C","body":"Multiple sources overwhelm a target’s resources"},{"label":"D","body":"One user reads an allowed document"}],"correct_option":"C","explanation":"Distributed sources can overload a service and impair availability.","answer_format":"standard","source_reference":"Supplied examination photo 4, Network models, firewalls and common threats [SHA-256 119c9dfa2ba2d363e147557a7d894bfe9c2a831e43613e94993e2c2e20e8b81b]"},{"course_code":"CYB 201","topic":2,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t2-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"The OSI layer concerned with routing is the ____ layer.","explanation":"The Network layer supports logical addressing and routing.","gaps":[{"index":0,"accepted_answers":["network"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 4, Network models, firewalls and common threats [SHA-256 119c9dfa2ba2d363e147557a7d894bfe9c2a831e43613e94993e2c2e20e8b81b]"},{"course_code":"CYB 201","topic":2,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t2-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"A security control that enforces network traffic rules is a ____.","explanation":"The reviewed lesson explains why the answer is firewall.","gaps":[{"index":0,"accepted_answers":["firewall"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 4, Network models, firewalls and common threats [SHA-256 119c9dfa2ba2d363e147557a7d894bfe9c2a831e43613e94993e2c2e20e8b81b]"},{"course_code":"CYB 201","topic":3,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t3-q1","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which key arrangement is characteristic of asymmetric cryptography?","options":[{"label":"A","body":"A public/private key pair"},{"label":"B","body":"One shared key only"},{"label":"C","body":"No keys for any operation"},{"label":"D","body":"Two identical public keys"}],"correct_option":"A","explanation":"Asymmetric systems use mathematically related public and private keys.","answer_format":"standard","source_reference":"Supplied examination photo 12, Cryptography, authentication and wireless security [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":3,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t3-q2","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which operation produces a digest rather than reversible ciphertext?","options":[{"label":"A","body":"Decryption"},{"label":"B","body":"Symmetric encryption"},{"label":"C","body":"Public-key encryption"},{"label":"D","body":"Hashing"}],"correct_option":"D","explanation":"A cryptographic hash maps data to a digest; it is not reversible encryption.","answer_format":"standard","source_reference":"Supplied examination photo 12, Cryptography, authentication and wireless security [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":3,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t3-q3","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which pairing combines two authentication factor types?","options":[{"label":"A","body":"A PIN and another PIN"},{"label":"B","body":"Two security questions"},{"label":"C","body":"A password and a physical security key"},{"label":"D","body":"Two passwords"}],"correct_option":"C","explanation":"The password is knowledge; the security key is possession.","answer_format":"standard","source_reference":"Supplied examination photo 12, Cryptography, authentication and wireless security [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":3,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t3-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which action makes network monitoring an active attack?","options":[{"label":"A","body":"Only observing metadata"},{"label":"B","body":"Altering intercepted messages"},{"label":"C","body":"Only listening to traffic"},{"label":"D","body":"Only recording packet timing"}],"correct_option":"B","explanation":"An active attacker modifies, injects or disrupts communications.","answer_format":"standard","source_reference":"Supplied examination photo 12, Cryptography, authentication and wireless security [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":3,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t3-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"Producing a non-reversible digest is called ____.","explanation":"A cryptographic hash maps data to a digest; it is not reversible encryption.","gaps":[{"index":0,"accepted_answers":["hashing"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 12, Cryptography, authentication and wireless security [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"CYB 201","topic":3,"photo_lesson":true,"logical_question_key":"cyb-201-photo20261025-t3-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"Cryptography using one shared secret key is ____ cryptography.","explanation":"The reviewed lesson explains why the answer is symmetric.","gaps":[{"index":0,"accepted_answers":["symmetric"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 12, Cryptography, authentication and wireless security [SHA-256 b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad]"},{"course_code":"IFT 212","topic":1,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t1-q1","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"A runs a workload in 5 s and B in 6 s. What is A’s performance relative to B?","options":[{"label":"A","body":"6 times B"},{"label":"B","body":"5 times B"},{"label":"C","body":"1.2 times B"},{"label":"D","body":"0.833 times B"}],"correct_option":"C","explanation":"For equal work, the ratio is 6/5 = 1.2.","answer_format":"standard","source_reference":"Supplied examination photo 3, Performance and the stored-program computer [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":1,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t1-q2","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"In a stored-program computer, where are instructions kept before execution?","options":[{"label":"A","body":"Nowhere until the user types them"},{"label":"B","body":"Memory"},{"label":"C","body":"Only on a printed flowchart"},{"label":"D","body":"Only in an output monitor"}],"correct_option":"B","explanation":"The processor fetches stored instructions from memory.","answer_format":"standard","source_reference":"Supplied examination photo 3, Performance and the stored-program computer [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":1,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t1-q3","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which metric expresses delay before a storage response?","options":[{"label":"A","body":"Latency"},{"label":"B","body":"Only physical colour"},{"label":"C","body":"Source-code line count"},{"label":"D","body":"Keyboard layout"}],"correct_option":"A","explanation":"Latency is elapsed delay associated with an operation.","answer_format":"standard","source_reference":"Supplied examination photo 3, Performance and the stored-program computer [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":1,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t1-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What is a key feature of a classic von Neumann memory organisation?","options":[{"label":"A","body":"Every instruction is hardwired manually"},{"label":"B","body":"Data cannot be stored"},{"label":"C","body":"No fetch step is required"},{"label":"D","body":"Instructions and data share a memory system"}],"correct_option":"D","explanation":"The stored-program organisation keeps data and instructions in memory.","answer_format":"standard","source_reference":"Supplied examination photo 3, Performance and the stored-program computer [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":1,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t1-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"A takes 5 s and B takes 6 s for the same workload. A’s performance is ____ times B’s.","explanation":"For equal work, the ratio is 6/5 = 1.2.","gaps":[{"index":0,"accepted_answers":["1.2","one point two"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 3, Performance and the stored-program computer [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":1,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t1-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"A stored-program computer keeps instructions in ____.","explanation":"The processor fetches stored instructions from memory.","gaps":[{"index":0,"accepted_answers":["memory","main memory"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 3, Performance and the stored-program computer [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":2,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t2-q1","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What does the program counter normally identify?","options":[{"label":"A","body":"The current monitor colour"},{"label":"B","body":"The next instruction’s location"},{"label":"C","body":"A user’s password"},{"label":"D","body":"The total number of printed pages"}],"correct_option":"B","explanation":"The program counter supports instruction sequencing.","answer_format":"standard","source_reference":"Supplied examination photo 3, CPU registers and bitwise operations [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":2,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t2-q2","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What is 1010₂ XOR 1100₂?","options":[{"label":"A","body":"0110₂"},{"label":"B","body":"1110₂"},{"label":"C","body":"1000₂"},{"label":"D","body":"0000₂"}],"correct_option":"A","explanation":"XOR marks bit positions where the operands differ.","answer_format":"standard","source_reference":"Supplied examination photo 3, CPU registers and bitwise operations [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":2,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t2-q3","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What is 1010₂ AND 1100₂?","options":[{"label":"A","body":"0110₂"},{"label":"B","body":"1110₂"},{"label":"C","body":"1010₂"},{"label":"D","body":"1000₂"}],"correct_option":"D","explanation":"Only the leading bit is 1 in both operands.","answer_format":"standard","source_reference":"Supplied examination photo 3, CPU registers and bitwise operations [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":2,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t2-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which expression equals (A XOR B) OR (A AND B)?","options":[{"label":"A","body":"A XOR B"},{"label":"B","body":"NOT A"},{"label":"C","body":"A OR B"},{"label":"D","body":"A AND B"}],"correct_option":"C","explanation":"The differing-bit and shared-1 cases together are exactly the OR cases.","answer_format":"standard","source_reference":"Supplied examination photo 3, CPU registers and bitwise operations [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":2,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t2-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"The register identifying the next instruction’s location is the ____.","explanation":"The reviewed lesson explains why the answer is program counter.","gaps":[{"index":0,"accepted_answers":["program counter","pc"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 3, CPU registers and bitwise operations [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 212","topic":2,"photo_lesson":true,"logical_question_key":"ift-212-photo20261025-t2-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"The bitwise operation that outputs 1 for differing input bits is ____.","explanation":"The reviewed lesson explains why the answer is xor.","gaps":[{"index":0,"accepted_answers":["xor","exclusive or","exclusive-or"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 3, CPU registers and bitwise operations [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"INS 204","topic":1,"photo_lesson":true,"logical_question_key":"ins-204-photo20261025-t1-q1","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which method obtains information by watching work as it occurs?","options":[{"label":"A","body":"Compilation"},{"label":"B","body":"Indexing code"},{"label":"C","body":"Observation"},{"label":"D","body":"Guessing requirements"}],"correct_option":"C","explanation":"Observation examines the process directly.","answer_format":"standard","source_reference":"Supplied examination photo 3, Feasibility, fact-finding and information-system components [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"INS 204","topic":1,"photo_lesson":true,"logical_question_key":"ins-204-photo20261025-t1-q2","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which method is suited to collecting structured responses from many users?","options":[{"label":"A","body":"A processor interrupt"},{"label":"B","body":"Questionnaire"},{"label":"C","body":"Replacing user consultation"},{"label":"D","body":"Changing code without analysis"}],"correct_option":"B","explanation":"Questionnaires can collect comparable responses at scale.","answer_format":"standard","source_reference":"Supplied examination photo 3, Feasibility, fact-finding and information-system components [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"INS 204","topic":1,"photo_lesson":true,"logical_question_key":"ins-204-photo20261025-t1-q3","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which list gives the stated five-component information-system model?","options":[{"label":"A","body":"Hardware, software, data, people, procedures"},{"label":"B","body":"Only keyboards and monitors"},{"label":"C","body":"Only software and source code"},{"label":"D","body":"Only routers and cables"}],"correct_option":"A","explanation":"This model includes technical, human and procedural components.","answer_format":"standard","source_reference":"Supplied examination photo 3, Feasibility, fact-finding and information-system components [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"INS 204","topic":1,"photo_lesson":true,"logical_question_key":"ins-204-photo20261025-t1-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What is a key purpose of feasibility analysis?","options":[{"label":"A","body":"Guarantee that future risks are impossible"},{"label":"B","body":"Replace all requirements work"},{"label":"C","body":"Choose implementation details without constraints"},{"label":"D","body":"Inform whether a proposal is practical and worthwhile"}],"correct_option":"D","explanation":"Feasibility weighs constraints and likely benefits before commitment.","answer_format":"standard","source_reference":"Supplied examination photo 3, Feasibility, fact-finding and information-system components [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"INS 204","topic":1,"photo_lesson":true,"logical_question_key":"ins-204-photo20261025-t1-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"Watching a business process directly is the fact-finding method called ____.","explanation":"Observation examines the process directly.","gaps":[{"index":0,"accepted_answers":["observation"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 3, Feasibility, fact-finding and information-system components [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"INS 204","topic":1,"photo_lesson":true,"logical_question_key":"ins-204-photo20261025-t1-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"A structured written set of questions for many users is a ____.","explanation":"Questionnaires can collect comparable responses at scale.","gaps":[{"index":0,"accepted_answers":["questionnaire"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 3, Feasibility, fact-finding and information-system components [SHA-256 e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b]"},{"course_code":"IFT 211","topic":1,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t1-q1","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What is the eight-bit two’s complement of 11100111₂?","options":[{"label":"A","body":"11100110₂"},{"label":"B","body":"00011010₂"},{"label":"C","body":"00011001₂"},{"label":"D","body":"00011000₂"}],"correct_option":"C","explanation":"Invert the bits to 00011000 and add one.","answer_format":"standard","source_reference":"Supplied examination photo 16, Number representation, BCD and two’s complement [SHA-256 b1b52d27992c7ff887769f431866f8e7e28a86df5f2304cb4de4f13666838422]"},{"course_code":"IFT 211","topic":1,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t1-q2","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What is 347₁₀ in BCD?","options":[{"label":"A","body":"0100 0011 0111"},{"label":"B","body":"0011 0100 0111"},{"label":"C","body":"101011011"},{"label":"D","body":"0011 0111 0100"}],"correct_option":"B","explanation":"Encode 3, 4 and 7 separately as 0011, 0100 and 0111.","answer_format":"standard","source_reference":"Supplied examination photo 16, Number representation, BCD and two’s complement [SHA-256 b1b52d27992c7ff887769f431866f8e7e28a86df5f2304cb4de4f13666838422]"},{"course_code":"IFT 211","topic":1,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t1-q3","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What does eight-bit signed-magnitude 11001100₂ represent?","options":[{"label":"A","body":"−76"},{"label":"B","body":"204"},{"label":"C","body":"76"},{"label":"D","body":"−52"}],"correct_option":"A","explanation":"The sign bit is 1; magnitude 1001100₂ is 64 + 8 + 4 = 76.","answer_format":"standard","source_reference":"Supplied examination photo 16, Number representation, BCD and two’s complement [SHA-256 b1b52d27992c7ff887769f431866f8e7e28a86df5f2304cb4de4f13666838422]"},{"course_code":"IFT 211","topic":1,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t1-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"What is 23.25₁₀ in binary?","options":[{"label":"A","body":"10111.1₂"},{"label":"B","body":"10110.01₂"},{"label":"C","body":"11011.01₂"},{"label":"D","body":"10111.01₂"}],"correct_option":"D","explanation":"23 is 10111₂ and one quarter is .01₂.","answer_format":"standard","source_reference":"Supplied examination photo 16, Number representation, BCD and two’s complement [SHA-256 b1b52d27992c7ff887769f431866f8e7e28a86df5f2304cb4de4f13666838422]"},{"course_code":"IFT 211","topic":1,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t1-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"The eight-bit two’s complement of 11100111 is ____. Write eight bits.","explanation":"Invert the bits to 00011000 and add one.","gaps":[{"index":0,"accepted_answers":["00011001"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 16, Number representation, BCD and two’s complement [SHA-256 b1b52d27992c7ff887769f431866f8e7e28a86df5f2304cb4de4f13666838422]"},{"course_code":"IFT 211","topic":1,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t1-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"Encoding each decimal digit separately in four bits is ____. Give the abbreviation.","explanation":"The reviewed lesson explains why the answer is bcd.","gaps":[{"index":0,"accepted_answers":["bcd"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 16, Number representation, BCD and two’s complement [SHA-256 b1b52d27992c7ff887769f431866f8e7e28a86df5f2304cb4de4f13666838422]"},{"course_code":"IFT 211","topic":2,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t2-q1","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which expression is equivalent to NOT(A AND B)?","options":[{"label":"A","body":"A AND B"},{"label":"B","body":"NOT A OR NOT B"},{"label":"C","body":"NOT A AND NOT B"},{"label":"D","body":"A OR B"}],"correct_option":"B","explanation":"De Morgan switches AND to OR and complements the operands.","answer_format":"standard","source_reference":"Supplied examination photo 15, Boolean algebra, truth tables and simplification [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":2,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t2-q2","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Simplify ¬P ∧ (P → Q).","options":[{"label":"A","body":"¬P"},{"label":"B","body":"P"},{"label":"C","body":"Q"},{"label":"D","body":"P ∧ Q"}],"correct_option":"A","explanation":"Replace implication with ¬P ∨ Q, then use X ∧ (X ∨ Y) = X.","answer_format":"standard","source_reference":"Supplied examination photo 15, Boolean algebra, truth tables and simplification [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":2,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t2-q3","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Simplify BC + ABC in Boolean algebra.","options":[{"label":"A","body":"ABC"},{"label":"B","body":"B + C"},{"label":"C","body":"A + BC"},{"label":"D","body":"BC"}],"correct_option":"D","explanation":"When BC is 1, OR with ABC adds no new true case.","answer_format":"standard","source_reference":"Supplied examination photo 15, Boolean algebra, truth tables and simplification [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":2,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t2-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which fact follows from the complement law?","options":[{"label":"A","body":"AA′ = 1"},{"label":"B","body":"A = A′"},{"label":"C","body":"A + A′ = 1"},{"label":"D","body":"A + A′ = 0"}],"correct_option":"C","explanation":"At least one of a Boolean variable and its complement is 1.","answer_format":"standard","source_reference":"Supplied examination photo 15, Boolean algebra, truth tables and simplification [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":2,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t2-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"Simplify ¬P ∧ (P → Q): ____.","explanation":"Replace implication with ¬P ∨ Q, then use X ∧ (X ∨ Y) = X.","gaps":[{"index":0,"accepted_answers":["¬P","not p","!p","~p"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 15, Boolean algebra, truth tables and simplification [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":2,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t2-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"In Boolean algebra A + A′ equals ____.","explanation":"At least one of a Boolean variable and its complement is 1.","gaps":[{"index":0,"accepted_answers":["1","one","true"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 15, Boolean algebra, truth tables and simplification [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":3,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t3-q1","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which gate outputs 1 only when both inputs are 1?","options":[{"label":"A","body":"AND"},{"label":"B","body":"OR"},{"label":"C","body":"NOT"},{"label":"D","body":"A buffer with one input"}],"correct_option":"A","explanation":"AND implements Boolean conjunction.","answer_format":"standard","source_reference":"Supplied examination photo 15, Logic gates and integrated circuits [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":3,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t3-q2","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which gate reverses a single binary input?","options":[{"label":"A","body":"OR"},{"label":"B","body":"AND"},{"label":"C","body":"A two-input adder only"},{"label":"D","body":"NOT"}],"correct_option":"D","explanation":"NOT is Boolean inversion.","answer_format":"standard","source_reference":"Supplied examination photo 15, Logic gates and integrated circuits [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":3,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t3-q3","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"Which is an example of an analogue integrated circuit?","options":[{"label":"A","body":"A binary counter only"},{"label":"B","body":"A Boolean flip-flop only"},{"label":"C","body":"An operational amplifier"},{"label":"D","body":"A digital AND gate"}],"correct_option":"C","explanation":"An operational amplifier processes continuously varying signal values.","answer_format":"standard","source_reference":"Supplied examination photo 15, Logic gates and integrated circuits [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":3,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t3-q4","pool":"learning","usage":["review","practice","mock"],"difficulty":"intermediate","prompt":"How is a two-variable Boolean identity verified by truth table?","options":[{"label":"A","body":"Assume similar symbols imply equality"},{"label":"B","body":"Compare both expressions on all four assignments"},{"label":"C","body":"Check only the 00 row"},{"label":"D","body":"Count letters in each expression"}],"correct_option":"B","explanation":"The expressions must agree for every possible input combination.","answer_format":"standard","source_reference":"Supplied examination photo 15, Logic gates and integrated circuits [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":3,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t3-gap1","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"The gate that outputs 1 only when both inputs are 1 is ____.","explanation":"AND implements Boolean conjunction.","gaps":[{"index":0,"accepted_answers":["and"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 15, Logic gates and integrated circuits [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"},{"course_code":"IFT 211","topic":3,"photo_lesson":true,"logical_question_key":"ift-211-photo20261025-t3-gap2","pool":"battle","usage":["battle"],"difficulty":"intermediate","prompt":"A gate that inverts its single input is ____.","explanation":"NOT is Boolean inversion.","gaps":[{"index":0,"accepted_answers":["not","inverter"]}],"answer_format":"fill_in_gap","battle_seconds":15,"battle_reading_seconds":8,"source_reference":"Supplied examination photo 15, Logic gates and integrated circuits [SHA-256 276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023]"}],"sources":[{"course_code":"AUE-GST 201","sha256":"05f45b10bf43fa16b051a2b4a71e50a7eb1c98d9bfaaa0f3e2606e1a4a7ffad4","object_key":"course-materials/05f45b10bf43fa16b051a2b4a71e50a7eb1c98d9bfaaa0f3e2606e1a4a7ffad4.pdf","filename":"philosophy 6-10.pdf","bytes":106083},{"course_code":"CSC 203","sha256":"b507716caa72d025e8a16c12adf64101c9eba05c5f2d1f76e6fb44ad50d35432","object_key":"course-materials/b507716caa72d025e8a16c12adf64101c9eba05c5f2d1f76e6fb44ad50d35432.txt","filename":"CSC 203 - Discrete Structures lessons 1-5.txt","bytes":8562},{"course_code":"COS 201","sha256":"823926c77e7deb6a77f2d648a9240ab5487165959a34a7b94c0775008aeb0cee","object_key":"course-materials/823926c77e7deb6a77f2d648a9240ab5487165959a34a7b94c0775008aeb0cee.jpg","filename":"COS 201 - supplied paper photo 1.jpg","bytes":72247},{"course_code":"CSC 203","sha256":"3146fe12bfcb3d170cfb96f9ead9e315c94dba9772f52cc0cb6f11bd0e21573a","object_key":"course-materials/3146fe12bfcb3d170cfb96f9ead9e315c94dba9772f52cc0cb6f11bd0e21573a.jpg","filename":"CSC 203 - supplied paper photo 2.jpg","bytes":61561},{"course_code":"SEN 201","sha256":"e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b","object_key":"course-materials/e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b.jpg","filename":"SEN 201 - supplied paper photo 3.jpg","bytes":70955},{"course_code":"CYB 201","sha256":"e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b","object_key":"course-materials/e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b.jpg","filename":"CYB 201 - supplied paper photo 3.jpg","bytes":70955},{"course_code":"IFT 212","sha256":"e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b","object_key":"course-materials/e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b.jpg","filename":"IFT 212 - supplied paper photo 3.jpg","bytes":70955},{"course_code":"INS 204","sha256":"e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b","object_key":"course-materials/e3cd4d32d884c1a25da9cede5a7cb281ee503f622f25fad26bb5f35e508ce57b.jpg","filename":"INS 204 - supplied paper photo 3.jpg","bytes":70955},{"course_code":"CYB 201","sha256":"119c9dfa2ba2d363e147557a7d894bfe9c2a831e43613e94993e2c2e20e8b81b","object_key":"course-materials/119c9dfa2ba2d363e147557a7d894bfe9c2a831e43613e94993e2c2e20e8b81b.jpg","filename":"CYB 201 - supplied paper photo 4.jpg","bytes":56988},{"course_code":"SEN 201","sha256":"d8afdf0885d35f5b5fc0035ad506525e74323fc15ef214bb39fe90933e5fe231","object_key":"course-materials/d8afdf0885d35f5b5fc0035ad506525e74323fc15ef214bb39fe90933e5fe231.jpg","filename":"SEN 201 - supplied paper photo 5.jpg","bytes":50829},{"course_code":"COS 201","sha256":"0ddec95c2c4048ef8e307abe08dfae931c61009ccba55e39c258a6c0d50e970c","object_key":"course-materials/0ddec95c2c4048ef8e307abe08dfae931c61009ccba55e39c258a6c0d50e970c.jpg","filename":"COS 201 - supplied paper photo 6.jpg","bytes":73083},{"course_code":"COS 201","sha256":"154729d6087f8caf24b4544e60204161082059cb7a22eefb85e47126d705325c","object_key":"course-materials/154729d6087f8caf24b4544e60204161082059cb7a22eefb85e47126d705325c.jpg","filename":"COS 201 - supplied paper photo 8.jpg","bytes":60059},{"course_code":"SEN 201","sha256":"9fe400b4c14505c025a738ed6fa9a8066f65a4a7afd67e38f3d7e1ddf048f31f","object_key":"course-materials/9fe400b4c14505c025a738ed6fa9a8066f65a4a7afd67e38f3d7e1ddf048f31f.jpg","filename":"SEN 201 - supplied paper photo 10.jpg","bytes":68177},{"course_code":"SEN 201","sha256":"4eee7e3965e391fcfa697fcc9a10219a4006ba0ea3eee14a97f8a14d2b304f78","object_key":"course-materials/4eee7e3965e391fcfa697fcc9a10219a4006ba0ea3eee14a97f8a14d2b304f78.jpg","filename":"SEN 201 - supplied paper photo 11.jpg","bytes":51256},{"course_code":"CYB 201","sha256":"b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad","object_key":"course-materials/b863060e16cacfdfe3bd696fa226c90ab2a9406e44abbc29196a2c32e6dfacad.jpg","filename":"CYB 201 - supplied paper photo 12.jpg","bytes":54952},{"course_code":"IFT 211","sha256":"276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023","object_key":"course-materials/276b2b0e4007553011a4f48b89fc7da81f5060724fab8f680e661d51f9fc4023.jpg","filename":"IFT 211 - supplied paper photo 15.jpg","bytes":46288},{"course_code":"IFT 211","sha256":"b1b52d27992c7ff887769f431866f8e7e28a86df5f2304cb4de4f13666838422","object_key":"course-materials/b1b52d27992c7ff887769f431866f8e7e28a86df5f2304cb4de4f13666838422.jpg","filename":"IFT 211 - supplied paper photo 16.jpg","bytes":43301}]}$reviewed_payload$::jsonb;
 actor uuid; row jsonb; item jsonb; result jsonb; lesson_result jsonb; question_rows jsonb:='[]';
 course uuid; lesson_id uuid; version_id uuid; assessment uuid; qids uuid[]; course_qids uuid[];
 chapter integer; kind text; title text; count_expected integer; ids uuid[]; n integer;
begin
 select user_id into actor from public.user_roles where role='admin' order by user_id limit 1;
 if actor is null then raise exception 'An administrator is required'; end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 perform set_config('request.headers','{"x-client-platform":"web","x-client-build":"1","x-api-version":"1"}',true);
 for row in select jsonb_build_object('code',value->>'course_code') from jsonb_array_elements(payload->'lessons') group by value->>'course_code' loop
   perform pg_advisory_xact_lock(hashtextextended('reviewed-content-20261025:'||(row->>'code'),0));
 end loop;
 for row in select value from jsonb_array_elements(payload->'lessons') loop
   if exists(select 1 from public.lessons l join public.modules m on m.id=l.module_id join public.courses c on c.id=l.course_id
     where c.code=row->>'course_code' and m.position=(row->>'module_position')::integer and l.position=(row->>'lesson_position')::integer
     and not (c.code='AUE-GST 201' and m.position=2 and l.position=1 and not exists(select 1 from public.lesson_versions lv where lv.lesson_id=l.id and lv.status in ('draft','published')))) then
     raise exception 'Target lesson slot has changed; review before importing: %',row->>'title';
   end if;
 end loop;
 result:=public.admin_import_lessons_v1(payload->'lessons',true,null);
 if result->>'valid' is distinct from 'true' then raise exception 'Lesson validation failed: %',result; end if;
 lesson_result:=public.admin_import_lessons_v1(payload->'lessons',false,gen_random_uuid());
 for item in select value from jsonb_array_elements(lesson_result->'created') loop
   perform public.admin_publish_v1('lesson_version',(item->>'lesson_version_id')::uuid,gen_random_uuid());
 end loop;
 for row in select value from jsonb_array_elements(payload->'questions') loop
   select (l->>'lesson_version_id')::uuid into version_id from jsonb_array_elements(lesson_result->'created') l
     where (payload->'lessons'->((l->>'row')::integer-1)->>'course_code')=row->>'course_code'
       and (payload->'lessons'->((l->>'row')::integer-1)->>'lesson_position')::integer=(row->>'topic')::integer
       and ((row->>'photo_lesson')::boolean is true) = ((payload->'lessons'->((l->>'row')::integer-1)->>'module_title')='Reviewed past-paper applications');
   if version_id is null then raise exception 'Question lesson could not be resolved: %',row->>'logical_question_key'; end if;
   select lv.lesson_id into lesson_id from public.lesson_versions lv where lv.id=version_id;
   question_rows:=question_rows||jsonb_build_array(row||jsonb_build_object('lesson_id',lesson_id));
 end loop;
 result:=public.admin_import_questions_v1(question_rows,true,null);
 if result->>'valid' is distinct from 'true' then raise exception 'Question validation failed: %',result; end if;
 result:=public.admin_import_questions_v1(question_rows,false,gen_random_uuid());
 for item in select value from jsonb_array_elements(result->'created') loop
   perform public.admin_publish_v1('question_version',(item->>'question_version_id')::uuid,gen_random_uuid());
 end loop;
 -- Per-lesson reviews: reuse the reviewed Philosophy source bank rather than duplicate it.
 for item in select value from jsonb_array_elements(lesson_result->'created') loop
   row:=payload->'lessons'->((item->>'row')::integer-1);
   lesson_id:=(item->>'lesson_id')::uuid;
   select c.id into course from public.courses c where c.code=row->>'course_code';
   if row->>'course_code'='AUE-GST 201' then
     chapter:=(row->>'lesson_position')::integer+5;
     select array_agg(qv.id order by q.logical_key) into qids from public.questions q
       join public.question_versions qv on qv.question_id=q.id where q.course_id=course and q.pool='learning'
       and qv.status='published' and qv.source_reference like '%05f45b10%' and qv.source_reference like '%chapter '||chapter||',%';
   else
     select array_agg(qv.id order by q.logical_key) into qids from public.questions q
       join public.question_versions qv on qv.question_id=q.id where q.lesson_id=lesson_id and q.pool='learning'
       and qv.status='published' and (q.logical_key like '%-source20261025-%' or q.logical_key like '%-photo20261025-%');
   end if;
   if coalesce(cardinality(qids),0)<1 then raise exception 'Lesson has no review bank: %',row->>'title'; end if;
   select a.id into assessment from public.assessments a where a.lesson_id=lesson_id and a.kind='review' order by a.created_at limit 1;
   result:=public.admin_upsert_assessment_draft_v1(assessment,course,'review',left((row->>'title')||' — Review',200),lesson_id,
     least(10,cardinality(qids)),null,qids,gen_random_uuid());
   perform public.admin_publish_v1('assessment_version',(result->>'assessment_version_id')::uuid,gen_random_uuid());
 end loop;
 for row in select jsonb_build_object('code',value->>'course_code') from jsonb_array_elements(payload->'lessons') group by value->>'course_code' loop
   select id into course from public.courses where code=row->>'code';
   select array_agg(qv.id order by q.logical_key) into course_qids from public.questions q join public.question_versions qv on qv.question_id=q.id
     where q.course_id=course and q.pool='learning' and qv.status='published' and
      (q.logical_key like '%-source20261025-%' or q.logical_key like '%-photo20261025-%' or (row->>'code'='AUE-GST 201' and qv.source_reference like '%05f45b10%'));
   foreach kind in array array['practice','mock'] loop
     title:='Reviewed source materials — '||case when kind='practice' then 'Practice' else 'Mock exam' end;
     select a.id into assessment from public.assessments a where a.course_id=course and a.lesson_id is null and a.kind=kind and a.title=title limit 1;
     n:=least(case when kind='practice' then 20 else 30 end,cardinality(course_qids));
     result:=public.admin_upsert_assessment_draft_v1(assessment,course,kind,title,null,n,
       case when kind='mock' then greatest(300,n*60) else null end,course_qids,gen_random_uuid());
     perform public.admin_publish_v1('assessment_version',(result->>'assessment_version_id')::uuid,gen_random_uuid());
   end loop;
 end loop;
 for row in select value from jsonb_array_elements(payload->'sources') loop
   select id into course from public.courses where code=row->>'course_code';
   insert into private.course_materials(course_id,sha256,object_key,filename,bytes,published)
     values(course,row->>'sha256',row->>'object_key',row->>'filename',(row->>'bytes')::bigint,true)
     on conflict(course_id,sha256) do update set published=true,updated_at=now();
 end loop;
 perform private.audit(actor,'publish_reviewed_materials','course_material_import',null,gen_random_uuid(),
   'Source-specific replacement and new user-provided study materials',jsonb_build_object('lessons',jsonb_array_length(payload->'lessons'),'questions',jsonb_array_length(payload->'questions')));
end $import$;
